def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def rev1(coord, p1, p2, agree=True):
    disp = "二路同点，保留主坐标。" if agree else "二路异坐标，无占优依据，主坐标降一档粒度为区间交付（R61-REV1-2）。"
    return ("R61-REV1-2 应期二路复推：初推=" + p1 + "，坐标=" + coord + "；复推=" + p2 + "，坐标=" + (coord if agree else "邻点异坐标") + "；处置=" + disp +
            "R61-REV1-3 尺度核：主坐标单位与(k)档位一致。R61-REV1-4 粒度核：处所/量级/状态类断项支撑指针>=2者原粒度保留、仅1条者已降为方位/区间/等级带，方向性主断不降档。R61-REV1-5：复核未变更终局方向。")

P = {}
def add(cid, trad, systems, pred, basis_core, conf, trig, rev):
    P[cid] = {"case_id": cid, "prediction_text": pred,
              "basis": "tradition=" + trad + "\nsystems_used=" + systems + "\n" + basis_core + "\n" + rev,
              "confidence": conf, "trigger": trig}
NT = T()

